def flatten(lst):
 r=[]
 for x in lst: r.extend(flatten(x)) if isinstance(x,list) else r.append(x)
 return r

def lcs_length(a,b):
 m,n=len(a),len(b);dp=[[0]*(n+1)for _ in range(m+1)]
 for i in range(m):
  for j in range(n):dp[i+1][j+1]=dp[i][j]+1 if a[i]==b[j]else max(dp[i+1][j],dp[i][j+1])
 return dp[m][n]

def group_anagrams(w):
 d={}
 for x in w:d.setdefault(tuple(sorted(x)),[]).append(x)
 return sorted([sorted(v)for v in d.values()])
